-- Sentinel Stream — ClickHouse schema
-- Generated by Claw-Data via Omega-Claw framework.
-- Apply with: docker compose exec clickhouse clickhouse-client --queries-file /docker-entrypoint-initdb.d/01-schema.sql

-- Core events table
CREATE TABLE IF NOT EXISTS sentinel_events (
    ts           DateTime64(3) CODEC(Delta, ZSTD),
    agent_id     LowCardinality(String),
    app_id       LowCardinality(String) DEFAULT 'default',
    event_type   Enum8(
        'prompt' = 1,
        'tool_call' = 2,
        'tool_response' = 3,
        'model_response' = 4,
        'retrieval' = 5,
        'action' = 6
    ),
    tool_name    LowCardinality(String) DEFAULT '',
    payload_hash String DEFAULT '',
    payload      String CODEC(ZSTD),
    tokens_in    UInt32 DEFAULT 0,
    tokens_out   UInt32 DEFAULT 0,
    user_id      LowCardinality(String) DEFAULT '',
    session_id   String DEFAULT '',
    risk_score   Float32 DEFAULT 0.0,
    flags        Array(String) DEFAULT []
) ENGINE = MergeTree()
PARTITION BY toStartOfMinute(ts)
ORDER BY (app_id, agent_id, ts)
SETTINGS index_granularity = 8192;

-- Pre-aggregated tool-call counts per (agent, tool, minute) — powers tool-abuse detector
CREATE MATERIALIZED VIEW IF NOT EXISTS sentinel_tool_calls_mv
ENGINE = SummingMergeTree()
PARTITION BY toStartOfMinute(ts)
ORDER BY (agent_id, tool_name, ts) AS
SELECT
    toStartOfMinute(ts) AS ts,
    agent_id,
    tool_name,
    count() AS call_count,
    sum(tokens_in) AS tokens_in_total,
    sum(tokens_out) AS tokens_out_total
FROM sentinel_events
WHERE event_type = 2 AND tool_name != ''
GROUP BY ts, agent_id, tool_name;

-- Alerts table
CREATE TABLE IF NOT EXISTS sentinel_alerts (
    ts           DateTime64(3),
    alert_type   LowCardinality(String),
    severity     Enum8('low' = 1, 'med' = 2, 'high' = 3, 'critical' = 4),
    agent_id     LowCardinality(String),
    event_ids    Array(String),
    technique    LowCardinality(String),   -- MITRE ATLAS technique ID
    summary      String,
    evidence     String CODEC(ZSTD),
    ch_query_ms  Float32 DEFAULT 0.0
) ENGINE = MergeTree()
PARTITION BY toStartOfDay(ts)
ORDER BY (severity, ts);

-- Helpful views for the dashboard
CREATE VIEW IF NOT EXISTS v_alerts_recent AS
SELECT ts, alert_type, severity, agent_id, technique, summary
FROM sentinel_alerts
ORDER BY ts DESC
LIMIT 100;

CREATE VIEW IF NOT EXISTS v_events_recent AS
SELECT ts, agent_id, event_type, tool_name, payload, risk_score, flags
FROM sentinel_events
ORDER BY ts DESC
LIMIT 500;
